    manager.stop("ghost");
    manager.stop("svc");
    assert.equal(manager.supervisors.size, 0);

    // startAll 跳过禁用服务器。
    store.upsert(normalizeServer(quietServer("off", { enabled: false })));
    manager.startAll();
    assert.ok(manager.supervisors.has("svc"));
    assert.ok(!manager.supervisors.has("off"), "禁用不启动");
