  assert.equal(listed.mode, "project");
  assert.equal(listed.totalServers, 3, "全部服务器（含 disabled/unavailable）");
  assert.equal(listed.totalTools, 3, "工具数不含 unavailable 服务器");
  assert.equal(listed.toolsTruncated, false);
